// Inputs chosen by visual play in Chromium, not generated by the beam search.
// Replays Clutterfunk's opening through both mirror portals (about 7.2%).
import assert from "node:assert/strict";
import { chromium } from "playwright";

const browser = await chromium.launch();
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on("pageerror", e => errors.push(e.message));
  await page.goto("http://localhost:3222/?level=11&manual=1");
  await page.waitForFunction(() => window.__play);
  const advance = async (ticks, held) => {
    if (held) await page.keyboard.down("Space");
    else await page.keyboard.up("Space");
    const alive = await page.evaluate(([ticks, held]) => {
      for (let i = 0; i < ticks; i++) if (!window.__play.stepTick(held)) return false;
      return true;
    }, [ticks, held]);
    assert.equal(alive, true, "the manually played route must remain alive");
  };
  const checkView = async mirrored => {
    const result = await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => {
      // Read after the game's frame draws. Ignore the progress bar and count
      // the default green icon in its normal (40%) and mirrored (60%) lanes.
      const canvas = document.querySelector("canvas");
      const gl = canvas.getContext("webgl2"), pixels = new Uint8Array(1280 * 720 * 4);
      gl.readPixels(0, 0, 1280, 720, gl.RGBA, gl.UNSIGNED_BYTE, pixels);
      const count = cx => {
        let n = 0;
        for (let y = 50; y < 500; y++) for (let x = cx - 48; x < cx + 48; x++) {
          const i = (y * 1280 + x) * 4;
          if (pixels[i + 1] > 180 && pixels[i + 1] > pixels[i] * 1.3 && pixels[i + 2] < 120) n++;
        }
        return n;
      };
      resolve({ mirrored: window.__play.info.mirrored, left: count(512), right: count(768) });
    })));
    assert.equal(result.mirrored, mirrored);
    assert.ok((mirrored ? result.right : result.left) > 250,
      `the icon must be visible in its ${mirrored ? "mirrored" : "normal"} lane: ${JSON.stringify(result)}`);
    assert.ok((mirrored ? result.left : result.right) < 100,
      "the previous player lane must be empty");
  };

  for (const [ticks, held] of [[75, false], [1, true], [25, false], [1, true],
    [55, false], [50, true], [26, false]]) await advance(ticks, held);
  await checkView(false);
  await advance(6, false); // orange mirror portal at x1223
  await checkView(true);
  await page.screenshot({ path: "/tmp/gd-mirror-entry-verified.png" });
  // Clear the pillars, drop beneath the saw, jump across the next saw, then
  // hold through the gravity pad and the inverted jump under the roof spike.
  for (const [ticks, held] of [[40, true], [37, false], [93, true]]) await advance(ticks, held);
  await checkView(false); // blue mirror portal at x2121
  await page.screenshot({ path: "/tmp/gd-mirror-exit-verified.png" });
  await page.keyboard.up("Space");
  await page.keyboard.press("Escape");
  assert.equal(await page.evaluate(() => window.__play.info.paused), true);
  assert.deepEqual(errors, []);
  console.log("PASS — manually chosen Clutterfunk route, mirror entry/exit pixels, pause");
} finally {
  await browser.close();
}
